import{_ as a}from"./chunks/02-model-link-create.GYs-TGFF.js";import{_ as e,o as r,c as l,a2 as o}from"./chunks/framework.z3u3TMv0.js";const i="/ultra_guides/shots/07-model-link-list.png",n="/ultra_guides/shots/08-model-settings.png",f=JSON.parse('{"title":"模型连接与参数","description":"","frontmatter":{"head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"模型连接与参数 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra user guides — AI roleplay, character cards, BYOK and local models."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/model-link"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/model-link"}]]},"headers":[],"relativePath":"manual/model-link.md","filePath":"manual/model-link.md","lastUpdated":1786517442000}'),d={name:"manual/model-link.md"};function s(p,t,h,u,c,m){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="模型连接与参数" tabindex="-1">模型连接与参数 <a class="header-anchor" href="#模型连接与参数" aria-label="Permalink to &quot;模型连接与参数&quot;">​</a></h1><p>BYOK：密钥保存在本机安全存储；请求直连你配置的地址。</p><p>没有付费 API 时，可先看 <a href="/ultra_guides/free-cloud/">免费云端</a>；本机部署见 <a href="/ultra_guides/local/">部署本地模型</a>。</p><h2 id="模型连接" tabindex="-1">模型连接 <a class="header-anchor" href="#模型连接" aria-label="Permalink to &quot;模型连接&quot;">​</a></h2><p>路径：<strong>设置 → 模型 → 模型连接</strong></p><p><img src="'+i+'" alt="模型连接列表"></p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>新建</td><td>平台、密钥、Base URL、模型</td></tr><tr><td>编辑 / 复制 / 删除</td><td>列表右侧菜单</td></tr><tr><td>设为默认</td><td>新对话默认使用</td></tr><tr><td>测连</td><td>保存前或编辑页「测试」</td></tr></tbody></table><h3 id="平台类型-常见" tabindex="-1">平台类型（常见） <a class="header-anchor" href="#平台类型-常见" aria-label="Permalink to &quot;平台类型（常见）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项（文案以 App 为准）</th><th>用途</th></tr></thead><tbody><tr><td>各云厂商预设</td><td>自动填国内/国际站 Base URL</td></tr><tr><td>自定义 (OpenAI 协议)</td><td>本地 Ollama / LM Studio、兼容网关</td></tr><tr><td>自定义 Gemini / Anthropic</td><td>对应协议端点</td></tr></tbody></table><p>多站点平台可切换「使用国际站」。本地模型详见 <a href="/ultra_guides/connect-app/minitavern">连接 MiniTavern</a> 与 <a href="/ultra_guides/local/tools">工具总览</a>。</p><p><img src="'+a+'" alt="新建连接"></p><h2 id="模型设置-全局参数" tabindex="-1">模型设置（全局参数） <a class="header-anchor" href="#模型设置-全局参数" aria-label="Permalink to &quot;模型设置（全局参数）&quot;">​</a></h2><p>路径：<strong>设置 → 模型设置</strong></p><p><img src="'+n+'" alt="模型设置"></p><p>常见项（名称以 App 为准）：</p><ul><li>记忆长度（历史条数相关）</li><li>回复令牌（max tokens；部分 Claude 场景<strong>不要</strong>设为 None）</li><li>Temperature、Top-P / Top-K</li><li>是否流式输出</li></ul><h2 id="会话级覆盖" tabindex="-1">会话级覆盖 <a class="header-anchor" href="#会话级覆盖" aria-label="Permalink to &quot;会话级覆盖&quot;">​</a></h2><p>路径：对话页 → <strong>设置</strong> → 模型连接 / 参数</p><p>可为单聊指定连接与采样，不改全局默认。</p><h2 id="聊天设置里的识图" tabindex="-1">聊天设置里的识图 <a class="header-anchor" href="#聊天设置里的识图" aria-label="Permalink to &quot;聊天设置里的识图&quot;">​</a></h2><p>路径：<strong>设置 → 聊天 → 识图设置</strong></p><ul><li>关闭「图片描写」：多模态直接把图送给模型（模型需支持视觉）。</li><li>开启：先描写再主模型（描写结果会缓存复用）。</li></ul><p>若报「当前模型不支持图片」，见 <a href="./errors#visionunsupported">错误排错 · visionUnsupported</a>。</p><h2 id="生图-连接-智能-关键词" tabindex="-1">生图（连接 / 智能 / 关键词） <a class="header-anchor" href="#生图-连接-智能-关键词" aria-label="Permalink to &quot;生图（连接 / 智能 / 关键词）&quot;">​</a></h2><p>路径：<strong>设置 → 生图</strong></p><ul><li><strong>生图连接 / 生图设置</strong>：API 与画质参数</li><li><strong>智能生图</strong>：开启后由模型判断是否需要生图；开启时不使用关键词规则</li><li><strong>关键词触发生图</strong>：智能关闭时可配置关键词自动生图</li></ul><p>本机 A1111 / ComfyUI：<a href="/ultra_guides/local/image-gen/">生图模型部署</a> · <a href="/ultra_guides/local/image-gen/connect-app">连 App</a>。<br> 云端免费档见 <a href="/ultra_guides/free-cloud/#免费生图怎么配">免费云端 · 生图</a>。</p><h2 id="排错入口" tabindex="-1">排错入口 <a class="header-anchor" href="#排错入口" aria-label="Permalink to &quot;排错入口&quot;">​</a></h2><p>测连或聊天失败 → Toast / 气泡 → <strong>查看详情</strong>（错误代码 + 原因 + 建议）→ 对照 <a href="./errors">错误代码排错</a>。</p>',29)])])}const b=e(d,[["render",s]]);export{f as __pageData,b as default};
